var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 1080, FH = 1520;
figDraw.viewbox(0, 0, FW, FH);
figDraw.rect(FW, FH).fill('#fff');

var gBand = figDraw.group();
var gHL = figDraw.group();
var gTree = figDraw.group();
var gText = figDraw.group();

var SERIF = '"Times New Roman",Times,Georgia,serif';
var C_COST = '#1a3f8f', C_UNRES = '#b5702a', C_OVER = '#a15c00';

/* ---------- helpers ---------- */
function mlabel(x, y, s, opt) {
