  document.getElementById('levelCostOverlayInput').checked = overlayOn;
}

/* ---------- interaction handlers ---------- */
function trigger_expansionStage() {
  stage = (stage + 1) % 4;
  syncUI(); figRender();
}
function update_problemSize(v) {
  nExp = +v; figRender();
}
function toggle_levelCostOverlay(on) {
  overlayOn = !!on; figRender();
}

/* ---------- demo step player ---------- */
var demoSteps = [
  {
    title: '(a) Start with T(n)',
    narration: 'The whole running time is a single unknown term T(n). Nothing is expanded yet — this is the recurrence in its most compact form.',
    state: { stage: 'T(n)', overlay: false, n: 16 }
  },
  {
    title: '(b) One substitution',
    narration: 'Applying T(n) = 2T(n/2) + cn once splits the term into a root of merge cost cn with two unresolved children T(n/2). The cn is the work done at this level only.',
    state: { stage: 'one split', overlay: false, n: 16 }
  },
  {
    title: '(c) Two substitutions',
    narration: 'Expanding both children turns each T(n/2) into a cost node cn/2 with two T(n/4) children. Notice the second level has two nodes of cost cn/2 — already summing to cn.',
    state: { stage: 'two splits', overlay: false, n: 16 }
  },
  {
    title: '(d) The full tree',
    narration: 'Keep substituting until every leaf is a base case of cost c. There are n leaves along the bottom, and the double-headed arrow on the left marks the height as lg n.',
    state: { stage: 'full tree', overlay: false, n: 16 }
  },
  {
    title: 'Add up each level',
    narration: 'Turn on the overlay: each row lights up and its dotted arrow reports the same total, cn. Node counts double while node costs halve, so the product never changes.',
    state: { stage: 'full tree', overlay: true, n: 16 }
  },
  {
    title: 'Grow n and watch the height',
    narration: 'Slide n upward by powers of two: the leaf row lengthens to n leaves and the tree gains one level per doubling. The lg n + 1 levels each cost cn, so Total = cn lg n + cn.',
    state: { stage: 'full tree', overlay: true, n: 256 }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + demoSteps.length) % demoSteps.length;
  var s = demoSteps[stepIdx];
  stage = stageNames.indexOf(s.state.stage);
  overlayOn = s.state.overlay;
  nExp = Math.round(Math.log(s.state.n) / Math.LN2);
  syncUI(); figRender();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + demoSteps.length + ' · ' + s.title;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
